      "url": "https://perthpipepower.com.au/fixtures-appliances-perth.html",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Does appliance connection include repairing the appliance itself?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Not automatically. Plumbing connections, fixed electrical work and an internal appliance fault are different scopes. Describe the problem or proposed installation so the relevant work can be confirmed before booking."
          }
        },
        {
          "@type": "Question",
          "name": "Can a supplied appliance be connected without changing pipework or wiring?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "That depends on its specifications, location and existing services. Ask the quote to separate the connection from any required pipe, cable, circuit or access work."
          }
        },
        {
          "@type": "Question",
          "name": "Is dishwasher installation the same as repairing a faulty dishwasher?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. A connection request concerns the water, drainage and any agreed electrical arrangements. An internal appliance fault is a separate service. Describe the model, intended location and task so the accepted scope can be confirmed."
          }
        },
        {
          "@type": "Question",
          "name": "Can I buy a replacement toilet before checking the connections?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Discuss the proposed product first. Dimensions, the existing connection position and access can affect installation. Confirm product supply, removal and any separate connection or restoration work before treating a product price as the full installed cost."
          }
        },
        {
          "@type": "Question",
          "name": "Why does the laundry drain overflow when the washing machine empties?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A waste-connection restriction or drainage problem is possible; appliance faults require a separate scope. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Can you replace leaking washing machine taps?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Repair or replacement of the water supply tap can be assessed separately from internal washing-machine repairs. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need detailed installation specifications before contacting you?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Tell us the fixture, equipment or upgrade you need and your Perth suburb. We assess the site and connections, confirm the requirements and qualified work arrangements and provide the written quote. Additional access is agreed with you first."
          }
        },
        {
          "@type": "Question",
          "name": "Can I send photos?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach a hazard, remove covers or dismantle equipment to take a photo."
          }
        },
        {
          "@type": "Question",
          "name": "What information helps with a fixture or appliance connection enquiry?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Include the fixture or appliance, the room, the issue you have noticed, the property address and whether water, drainage or electrical supply is involved."
          }
        },
        {
          "@type": "Question",
          "name": "Can plumbing and electrical work be considered together?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Explain the complete requirement so the relevant plumbing and electrical work can be considered as part of the scope."
          }
        },
        {
          "@type": "Question",
          "name": "How is the work priced?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing is based on the agreed scope, property access, materials or parts required and the condition confirmed through the enquiry or assessment process."
          }
        },
        {
          "@type": "Question",
          "name": "Does appliance connection include appliance servicing?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Connection work and repair of the appliance itself are different services. We identify the installation and connection tasks in the written quote and explain the boundary if the request involves an internal appliance fault."
          }
        }
